def resolve(path, cwd, links):
    if links is None:
        links = {}

    link_count = 0
    max_links = 8

    # Determine starting point
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    # Split path into components
    components = remaining.split('/')

    i = 0
    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append component to current path
        if current == '/':
            next_path = '/' + component
        else:
            next_path = current + '/' + component

        # Check if it's a symlink
        if next_path in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[next_path]

            # Resolve remaining components after current one
            remaining_components = components[i+1:]

            # Handle the target
            if target.startswith('/'):
                current = '/'
                target_components = target[1:].split('/')
            else:
                # Target is relative to the directory containing the link
                if next_path == '/':
                    current = '/'
                else:
                    current = next_path.rsplit('/', 1)[0]
                target_components = target.split('/')

            # Combine target components with remaining components
            components = target_components + remaining_components
            i = 0
            continue

        current = next_path
        i += 1

    # Return result without trailing slash (except for '/')
    if current == '/':
        return '/'
    else:
        return current

